tElementById('command'),send=document.getElementById('send'),voice=document.getElementById('voice'),statusEl=document.getElementById('status'),openai=document.getElementById('openai'),admin=document.getElementById('admin'),err=document.getElementById('error'),resp=document.getElementById('response'),plan=document.getElementById('plan'),agents=document.getElementById('agents'),count=document.getElementById('count'),history=document.getElementById('history');function badge(el,text,kind){el.textContent=text;el.className='badge '+kind}function setStatus(t,k){statusEl.textContent=t;statusEl.className='status '+k}function showErr(t){err.textContent=t;err.classList.toggle('show',!!t)}function log(t,s){if(history.classList.contains('empty')){history.className='';history.textContent=''}const d=document.createElement('div');d.className='agent';d.textContent=new Date().toLocaleTimeString()+' — '+s+': '+t.slice(0,100);history.prepend(d)}function render(p){resp.className='';resp.textContent=p.goal+'\n\nRisk: '+p.risk_level+'\nMissing information: '+(p.missing_information.length?p.missing_information.join('; '):'None')+'\nApprovals required: '+(p.approvals_required.length?p.approvals_required.map(x=>x.type+': '+x.reason).join('; '):'None');plan.innerHTML='';p.steps.forEach(s=>{const li=document.createElement('li');const b=document.createElement('b');b.textContent='Step '+s.step_number+' — '+s.agent;const d=document.createElement('div');d.className='muted';d.textContent=s.action;li.append(b,d);plan.appendChild(li)});agents.innerHTML='';if(!p.required_agents.length){agents.innerHTML='<div class="empty">No agents required.</div>';return}p.required_agents.forEach(a=>{const d=document.createElement('div');d.className='agent';const n=document.createElement('span');n.textContent=a;const s=document.createElement('span');s.className='planned';s.textContent='Planned only';d.append(n,s);agents.appendChild(d)})}async function health(){try{const r=await fetch('/rainbow-ai/health.php',{credentials:'same-origin',cache:'no-store'}),d=await r.json();if(d.security.admin_configured)badge(admin,d.security.authenticated?'Authenticated':'Login Required',d.security.authenticated?'ok':'warn');else badge(admin,'Not Configured','bad');if(d.openai.connected){badge(openai,'Connected','ok');setStatus('OpenAI Connected','connected')}else if(d.openai.configured){badge(openai,'Configured / Locked','warn');setStatus('OpenAI Not Verified','failed')}else{badge(openai,'Not Connected','bad');setStatus('OpenAI Not Connected','failed')}}catch(e){badge(openai,'Health Check Failed','bad');setStatus('Connection Check Failed','failed')}}q.addEventListener('input',()=>count.textContent=q.value.length+' / 4000');send.addEventListener('click',async()=>{const text=q.value.trim();showErr('');if(text.length<3){showErr('Enter at least 3 characters.');return}send.disabled=voice.disabled=true;send.textContent='Sending…';setStatus('Planning…','');resp.className='empty';resp.textContent='Waiting for OpenAI response…';try{const r=await fetch('/rainbow-ai/orchestrate.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({command:text})});let d;try{d=await r.json()}catch{throw new Error('Server returned an invalid response.')}if(!r.ok||!d.ok)throw new Error(d.message||'Command failed.');render(d.plan);log(text,'Plan received');setStatus('OpenAI Connected','connected');badge(openai,'Connected','ok')}catch(e){resp.className='empty';resp.textContent='No plan received.';showErr(e.message||'Command failed.');log(text,'Failed');setStatus('Request Failed','failed')}finally{send.disabled=voice.disabled=false;send.textContent='Send Command'}});const SR=window.SpeechRecognition||window.webkitSpeechRecognition;if(SR){voice.addEventListener('click',()=>{const r=new SR();r.lang='en-IN';r.interimResults=false;voice.disabled=true;voice.textContent='Listening…';r.onresult=e=>{q.value=e.results[0][0].transcript;q.dispatchEvent(new Event('